import{_ as r,l,o as a,c as i,v as t,p as c,x as o,d,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"稀疏文件与穿孔","description":"","frontmatter":{"title":"稀疏文件与穿孔","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sparse-files.md","filePath":"cs/sparse-files.md","lastUpdated":1789023840000}'),E={name:"cs/sparse-files.md"};function h(_,e,f,m,u,A){const s=l("Mermaid");return a(),i("div",null,[e[1]||(e[1]=t('<h1 id="稀疏文件与穿孔" tabindex="-1">稀疏文件与穿孔 <a class="header-anchor" href="#稀疏文件与穿孔" aria-label="Permalink to &quot;稀疏文件与穿孔&quot;">​</a></h1><div class="epigraph"><p>逻辑大小可以盖住从未分配的洞；读洞得零。穿孔把已分配块还回去，使中间再次变成洞。</p><footer>—— 据 POSIX lseek 与 <code>FALLOC_FL_PUNCH_HOLE</code>；McKusick 对空洞文件的讨论</footer></div><p><a href="/cs/fs-mmap-coherence">上一课</a>假定偏移对应页。若从未写入某偏移，<a href="/cs/ext4-extents">extent</a> 可以不覆盖它，FAT 链也可以跳过——但接口要统一：<strong>稀疏文件</strong>。缺口是洞的 POSIX 语义与 <code>fallocate</code> 穿孔，不是再讲块组位图。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>虚拟机镜像、下载占位、科学数据经常「中间没有写过」。若按逻辑大小预分配，盘瞬间满。Unix 约定：<code>lseek</code> 越过 EOF 再写，中间是洞；<code>read</code> 洞返回零，不占块。穿孔：已有数据的区间也可以改回洞，释放块，再次读零。缺口：<code>SEEK_HOLE</code>/<code>SEEK_DATA</code> 如何让工具跳过洞；mmap 洞页是零页还是写时分配；与配额、快照的交叉（穿孔是否立刻减占用）。</p><p><span class="marginnote"><code>fallocate</code> 预分配与穿孔是同一系统调用的不同模式。预分配减少碎片，与稀疏相反。教学上两者都改「逻辑 vs 物理」关系。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>FS：洞不出现在块图/extent/FAT 链中。写洞中某页：分配块，插入图，页缓存从零页变成普通脏页。穿孔：切 extent 或拆链，位图清位，作废页缓存对应页。与 COW：穿孔是新树，旧快照仍握旧块。与 <a href="/cs/fsck">fsck</a>：洞不是交叉，位图空闲而逻辑大小盖住是合法。</p>',8)),(a(),c(p,null,{default:o(()=>[n(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20LSIZE%5B%22%E9%80%BB%E8%BE%91%E5%A4%A7%E5%B0%8F%22%5D%20--%3E%20HOLE%5B%22%E6%9C%AA%E8%A6%86%E7%9B%96%E5%81%8F%E7%A7%BB%22%5D%0A%20%20HOLE%20--%3E%20RZ%5B%22read%20%E5%BE%97%E9%9B%B6%22%5D%0A%20%20PUNCH%5B%22punch%20hole%22%5D%20--%3E%20FREE%5B%22%E8%BF%98%E5%9D%97%22%5D%0A%20%20FREE%20--%3E%20HOLE%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>稀疏把「文件」从「已占用块的集合」里解放出来：对象是逻辑字节数组，物理是部分函数。备份工具若按逻辑大小拷会把洞物化成零，撑爆目标——必须懂 <code>SEEK_HOLE</code>。不要把洞写成数据库 NULL：没有列，只有偏移。</p><p>mmap 共享映射写洞会分配并标脏，等于物化。私有映射写洞只物化匿名页，文件仍稀疏。</p><p>实现上：SEEK_HOLE 的精度取决于 FS：有的按 extent，有的只在整个文件级。备份若忽略它会把 TB 级洞物化成零。fallocate 预分配则相反，故意让洞消失以减运行时分配。 读法上只引用<a href="/cs/fs-mmap-coherence">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 布局与日志」课序里，对象是 <strong>稀疏文件与穿孔</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不保证网络 FS 上穿孔的每一种缓存失效。不引入压缩：压缩后「洞」与「压缩零」不同，那是具体 FS 附录。下一课把「数据块之外」的旁路字节：扩展属性与 ACL。</p><p>版本字段会变，课序钉的是机制对象「稀疏文件与穿孔」，不是某一主线内核的结构体名。 后课默认：逻辑空洞合法且可读零。名空间里的权限与键值元数据，下一课 xattr/ACL。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>洞不占块；read 零；穿孔归还已分配块。</li><li>快照可保留穿孔前的块。</li><li>扩展属性与 ACL 是下一课。</li><li>出处：POSIX；Linux fallocate；McKusick；<em>OSTEP</em>。</li></ul>',11))])}const T=r(E,[["render",h]]);export{x as __pageData,T as default};
